from django.utils import timezone
from django.utils.html import escape


class GlobalToolbarMiddleware:
    def __init__(self, get_response):
        self.get_response = get_response

    def __call__(self, request):
        response = self.get_response(request)
        if 'text/html' not in response.get('Content-Type', '') or not hasattr(response, 'content'):
            return response
        user = getattr(request, 'user', None)
        username = user.get_username() if user and user.is_authenticated else 'مهمان'
        stamp = timezone.localtime().strftime('%Y/%m/%d - %H:%M')
        toolbar = f'''<div class="darman-global-toolbar"><a href="/">صفحه اصلی</a><a href="/laboratory/">کارتابل آزمایشگاه</a><span>تاریخ و ساعت سیستم: {escape(stamp)}</span><span>کاربر: {escape(username)}</span></div><style>.darman-global-toolbar{{position:fixed;z-index:9999;bottom:0;right:0;left:0;display:flex;justify-content:center;gap:20px;padding:7px 12px;background:#18323a;color:#fff;font:11px Tahoma;box-shadow:0 -2px 8px #0002}}.darman-global-toolbar a{{color:#bde8dc;text-decoration:none;font-weight:bold}}body{{font-family:Tahoma,Arial,sans-serif!important;background:#f3f7f8!important}}button,input,select,textarea{{font-family:Tahoma,Arial,sans-serif!important}}.hero a{{display:none!important}}.box,.card,.panel,.list{{box-shadow:0 8px 24px #18323a0d;border-radius:16px}}.grid,.layout{{grid-template-columns:minmax(360px,1fr) minmax(360px,1fr)!important;align-items:start!important;gap:18px!important}}.wrap,.app{{max-width:1280px!important;padding:22px!important}}.box label,.card label,.panel label{{margin-top:8px!important;margin-bottom:3px!important;font-size:12px!important}}.box input,.box select,.box textarea,.card input,.card select,.card textarea,.panel input,.panel select,.panel textarea{{padding:8px!important;margin-top:3px!important;margin-bottom:7px!important;border-radius:9px!important}}@media(max-width:850px){{.grid,.layout{{grid-template-columns:1fr!important}}}}@media print{{.darman-global-toolbar{{display:none}}}}</style>'''.encode('utf-8')
        if request.path == '/':
            response.content = response.content.replace(b'<a class="module" href="/imaging/">', '<a class="module" href="/laboratory/"><div class="mini">🧪</div><div><h3>آزمایشگاه</h3><p>پذیرش آزمایش، نمونه‌گیری و ثبت نتایج</p></div></a><a class="module" href="/imaging/">'.encode('utf-8'), 1)
            toolbar += '<a href="/laboratory/" style="position:fixed;bottom:48px;right:24px;z-index:9998;background:#138576;color:#fff;padding:12px 18px;border-radius:10px;text-decoration:none;font:13px Tahoma">🧪 کارتابل آزمایشگاه</a>'.encode('utf-8')
        if request.path.rstrip('/') == '/definitions/setup/services':
            response.content = response.content.replace(b'</main>', '<a href="/definitions/services/export/" style="position:fixed;top:70px;left:24px;z-index:9998;background:#147d70;color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font:12px Tahoma">دریافت Excel خدمات نمایش‌داده‌شده</a></main>'.encode('utf-8'), 1)
        if request.path.rstrip('/') == '/imaging':
            response.content = response.content.replace("option.textContent.startsWith(g.textContent+' —')".encode('utf-8'), "option.textContent.includes(' — '+g.textContent+' —')".encode('utf-8'))
        if any(request.path.startswith(prefix) for prefix in ('/reception', '/beauty', '/dentistry', '/imaging', '/laboratory')):
            if request.path.rstrip('/') == '/reception':
                lookup = '''<script>document.addEventListener('DOMContentLoaded',function(){const input=document.getElementById('id_service_code');if(!input)return;let timer,sequence=0;async function show(){const q=input.value.trim(),id=++sequence;if(!q)return;try{const response=await fetch('/reception/service-lookup/?q='+encodeURIComponent(q));if(!response.ok)return;const data=await response.json();if(id!==sequence||input.value.trim()!==q)return;const exact=data.items.find(x=>(x.code||'').toLowerCase()===q.toLowerCase());if(exact){input.value=exact.name;input.dispatchEvent(new Event('change'))}}catch(e){}}input.addEventListener('input',function(){clearTimeout(timer);timer=setTimeout(show,500)});input.addEventListener('change',show)});</script>'''.encode('utf-8')
                marker = b'</body>' if b'</body>' in response.content else b'</html>'
                response.content = response.content.replace(marker, lookup + marker, 1)
            if request.path.rstrip('/') in ('/beauty', '/dentistry/admission'):
                layout = '''<style>form.panel[method=post],form.card[method=post]{display:grid!important;grid-template-columns:auto minmax(120px,1fr) auto minmax(120px,1fr);gap:8px 12px;align-items:center;max-width:none!important}form.panel[method=post]>h2,form.card[method=post]>h2,form.panel[method=post]>button,form.card[method=post]>button{grid-column:1/-1}form.panel[method=post]>label,form.card[method=post]>label{margin:0!important;white-space:normal}form.panel[method=post]>input:not([type=hidden]),form.panel[method=post]>select,form.panel[method=post]>textarea,form.card[method=post]>input:not([type=hidden]),form.card[method=post]>select,form.card[method=post]>textarea{width:100%;min-width:0;box-sizing:border-box;margin:0!important;padding:7px!important}form.panel[method=post]>input[type=hidden],form.card[method=post]>input[type=hidden]{display:none}@media(max-width:700px){form.panel[method=post],form.card[method=post]{grid-template-columns:auto minmax(0,1fr)}}</style>'''.encode('utf-8')
                marker = b'</body>' if b'</body>' in response.content else b'</html>'
                response.content = response.content.replace(marker, layout + marker, 1)
            compact = '''<style>.darman-admission-form,.admission-form,.box form,form.box{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px 14px;align-items:end}.darman-admission-form>h1,.darman-admission-form>h2,.darman-admission-form>.hint,.darman-admission-form>button,.admission-form>h1,.admission-form>h2,.admission-form>.hint,.admission-form>button,.box form>h1,.box form>h2,.box form>.hint,.box form>button,form.box>h1,form.box>h2,form.box>button{grid-column:1/-1}.darman-admission-form label,.admission-form label,.box form label,form.box label{margin:0!important}.darman-admission-form input,.darman-admission-form select,.darman-admission-form textarea,.admission-form input,.admission-form select,.admission-form textarea,.box form input,.box form select,.box form textarea,form.box input,form.box select,form.box textarea{width:100%;min-width:0;padding:7px!important;margin:2px 0 0!important;height:38px}.form-row,form.box>p{margin:0!important;min-width:0}form.box>p{display:flex;flex-direction:column}darman-admission-form textarea,.admission-form textarea,.box form textarea{height:auto}.darman-admission-form button,.admission-form button,.box form button,form.box button{margin-top:8px!important}@media(max-width:900px){.darman-admission-form,.admission-form,.box form,form.box{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:560px){.darman-admission-form,.admission-form,.box form,form.box{grid-template-columns:1fr}}</style>'''.encode('utf-8')
            marker = b'</body>' if b'</body>' in response.content else b'</html>'
            response.content = response.content.replace(marker, compact + marker, 1)
        jalali = '''<style>.darman-jalali-picker{position:absolute;z-index:10000;background:#fff;border:1px solid #c9dce5;border-radius:10px;box-shadow:0 8px 22px #18323a33;padding:8px;width:240px}.darman-jalali-picker .head{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px}.darman-jalali-picker button{padding:5px 8px;border:0;border-radius:5px;background:#e8f4f1;color:#146c64;cursor:pointer}.darman-jalali-picker .days{display:grid;grid-template-columns:repeat(7,1fr);gap:3px}.darman-jalali-picker .days button{background:#f5f8fa;color:#18323a}.darman-jalali-picker .days button:hover{background:#147d70;color:#fff}</style><script>(function(){const names=['date_from','date_to','start_date','end_date','schedule_date','next_session_date'];const ms=['فروردین','اردیبهشت','خرداد','تیر','مرداد','شهریور','مهر','آبان','آذر','دی','بهمن','اسفند'];function pad(n){return String(n).padStart(2,'0')}function toPersianDigits(s){return s.replace(/[0-9]/g,x=>'۰۱۲۳۴۵۶۷۸۹'[x])}function setup(i){if(i.dataset.jalaliReady)return;i.dataset.jalaliReady='1';if(i.type==='date'){i.type='text';i.placeholder='۱۴۰۵/۰۸/۱۰'}i.setAttribute('autocomplete','off');let box;function close(){if(box){box.remove();box=null}}i.addEventListener('click',e=>{e.stopPropagation();close();let now=new Date(),y=now.getFullYear()-621,m=now.getMonth()+1;box=document.createElement('div');box.className='darman-jalali-picker';box.style.position='absolute';const r=i.getBoundingClientRect();box.style.top=(window.scrollY+r.bottom+4)+'px';box.style.left=(window.scrollX+r.left)+'px';function draw(){let days=m<=6?31:m<=11?30:29;box.innerHTML='<div class="head"><button type="button" data-p>ماه قبل</button><b>'+ms[m-1]+' '+y+'</b><button type="button" data-n>ماه بعد</button></div><div class="days">'+Array.from({length:days},(_,n)=>'<button type="button" data-d="'+(n+1)+'">'+toPersianDigits(String(n+1))+'</button>').join('')+'</div>';box.querySelector('[data-p]').onclick=()=>{m--;if(m<1){m=12;y--}draw()};box.querySelector('[data-n]').onclick=()=>{m++;if(m>12){m=1;y++}draw()};box.querySelectorAll('[data-d]').forEach(b=>b.onclick=()=>{i.value=y+'/'+pad(m)+'/'+pad(b.dataset.d);i.dispatchEvent(new Event('change',{bubbles:true}));close()})}draw();document.body.appendChild(box)});document.addEventListener('click',e=>{if(box&&!box.contains(e.target)&&e.target!==i)close()})}document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('input[name="date_from"],input[name="date_to"],input[name="start_date"],input[name="end_date"],input[name="schedule_date"],input[name="next_session_date"],input[type="date"]').forEach(setup)})})();</script>'''.encode('utf-8')
        marker = b'</body>' if b'</body>' in response.content else b'</html>'
        response.content = response.content.replace(marker, jalali + marker, 1)
        marker = b'</body>'
        if marker in response.content:
            response.content = response.content.replace(marker, toolbar + marker, 1)
        return response
